INSERT INTO public.chapters VALUES ('33186d93-6188-4ae3-92c4-aac950047b8e', 'e49872b4-ff93-4cff-8576-c518de829a27', 'Chapitre 1 : Le Cercle des Curieux', '', 0, 'planned', '', '2025-08-24 13:13:56.851924', '2025-08-24 13:14:46.224');
INSERT INTO public.chapters VALUES ('501cf279-db16-4a9c-8a61-ae2ece10ebc7', '4ecf830f-3c1b-4b47-a5e8-1a1ab97cd75e', 'Chapitre I : Les Disparitions Mystérieuses', 'Des personnalités influentes disparaissent sans laisser de traces dans les rues brumeuses de Paris. Les investigateurs sont appelés pour élucider ces mystères.', 1, 'active', NULL, '2025-12-31 09:48:45.180236', '2025-12-31 09:48:45.180236');
INSERT INTO public.chapters VALUES ('a517f1d4-23fe-4b4a-bcd1-24a990449617', '4ecf830f-3c1b-4b47-a5e8-1a1ab97cd75e', 'Chapitre II : Le Culte des Ombres', 'La piste mène à une société secrète opérant dans les catacombes de Paris. Les investigateurs découvrent des rituels anciens et des forces obscures.', 2, 'planned', NULL, '2025-12-31 09:48:45.180236', '2025-12-31 09:48:45.180236');
INSERT INTO public.chapters VALUES ('bbbb8a2d-1b47-4d80-ac1f-67bcafe0e9d5', 'e49872b4-ff93-4cff-8576-c518de829a27', 'Chapitre 2 : Le Manoir Abandonné', 'Les investigateurs suivent une piste menant à un vieux manoir en dehors de Paris, où des choses étranges se produisent la nuit.', 1, 'planned', NULL, '2025-12-31 09:53:38.346069', '2025-12-31 09:53:38.346069');
INSERT INTO public.chapter_events VALUES ('1b6472b6-09d6-441c-ab9d-53004b139274', '33186d93-6188-4ae3-92c4-aac950047b8e', 'e49872b4-ff93-4cff-8576-c518de829a27', 'narration', 'Réunion Du Cercle', 'Lieu : une arrière-salle miteuse près de la Gare de l’Est. Murs jaunis, bougies qui vacillent, quelques tables branlantes couvertes de vieux journaux, fioles étranges, cartes de France où des épingles marquent des “phénomènes curieux”.
